1	/*
2	 * AI模拟面试官 — 状态机实现
3	 * 负责：B同学
4	 * IDLE -> RECORDING -> UPLOADING -> PLAYING -> IDLE
5	 */
6	
7	#include <stdio.h>
8	#include "state_machine.h"
9	
10	static system_state_t g_current_state = STATE_IDLE;
11	static int g_retry_count = 0;
12	#define MAX_RETRY_COUNT 3
13	
14	static const char* state_names[] = {"IDLE", "RECORDING", "UPLOADING", "PLAYING", "ERROR"};
15	static const char* event_names[] = {"BUTTON_PRESS", "RECORD_DONE", "RECORD_TIMEOUT", "UPLOAD_SUCCESS", "UPLOAD_FAIL", "PLAY_DONE", "RETRY", "ERROR"};
16	
17	static system_state_t get_next_state(system_state_t current, system_event_t event)
18	{
19	    switch (current) {
20	        case STATE_IDLE:
21	            if (event == EVENT_BUTTON_PRESS) { g_retry_count = 0; return STATE_RECORDING; }
22	            return current;
23	        case STATE_RECORDING:
24	            if (event == EVENT_RECORD_DONE || event == EVENT_RECORD_TIMEOUT) return STATE_UPLOADING;
25	            if (event == EVENT_ERROR) return STATE_IDLE;
26	            return current;
27	        case STATE_UPLOADING:
28	            if (event == EVENT_UPLOAD_SUCCESS) return STATE_PLAYING;
29	            if (event == EVENT_UPLOAD_FAIL) {
30	                g_retry_count++;
31	                if (g_retry_count >= MAX_RETRY_COUNT) return STATE_IDLE;
32	                return STATE_ERROR;
33	            }
34	            return current;
35	        case STATE_PLAYING:
36	            if (event == EVENT_PLAY_DONE) return STATE_IDLE;
37	            return current;
38	        case STATE_ERROR:
39	            if (event == EVENT_BUTTON_PRESS) { g_retry_count = 0; return STATE_IDLE; }
40	            if (event == EVENT_RETRY) return STATE_UPLOADING;
41	            return current;
42	    }
43	    return STATE_IDLE;
44	}
45	
46	static void update_led_by_state(system_state_t state)
47	{
48	    switch (state) {
49	        case STATE_IDLE:     led_set(LED_GREEN, LED_MODE_ON); break;
50	        case STATE_RECORDING: led_set(LED_RED, LED_MODE_BLINK); break;
51	        case STATE_UPLOADING: led_set(LED_BLUE, LED_MODE_BREATH); break;
52	        case STATE_PLAYING:  led_set(LED_GREEN, LED_MODE_ON); break;
53	        case STATE_ERROR:    led_set(LED_RED, LED_MODE_ON); break;
54	    }
55	}
56	
57	void state_machine_init(void)
58	{
59	    g_current_state = STATE_IDLE;
60	    g_retry_count = 0;
61	    printf("[StateMachine] 初始化完成，当前状态: %s\n", state_names[g_current_state]);
62	    update_led_by_state(STATE_IDLE);
63	}
64	
65	void state_machine_post_event(system_event_t event)
66	{
67	    system_state_t new_state = get_next_state(g_current_state, event);
68	    if (new_state != g_current_state) {
69	        printf("[StateMachine] %s --[%s]--> %s\n", state_names[g_current_state], event_names[event], state_names[new_state]);
70	        g_current_state = new_state;
71	        update_led_by_state(new_state);
72	        switch (new_state) {
73	            case STATE_RECORDING: printf("[StateMachine] 开始录音...\n"); break;
74	            case STATE_UPLOADING: printf("[StateMachine] 开始上传音频...\n"); break;
75	            case STATE_PLAYING:   printf("[StateMachine] 开始播放...\n"); break;
76	            case STATE_ERROR:     printf("[StateMachine] 错误状态，等待处理...\n"); break;
77	            default: break;
78	        }
79	    }
80	}
81	
82	system_state_t state_machine_get_current_state(void) { return g_current_state; }
83	int state_machine_is_busy(void) {
84	    return (g_current_state == STATE_RECORDING || g_current_state == STATE_UPLOADING || g_current_state == STATE_PLAYING);
85	}
86	
87	void led_set(led_color_t color, led_mode_t mode)
88	{
89	    printf("[LED] 颜色=%d, 模式=%d\n", color, mode);
90	}
